content.css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent;
}
.snow-empty-state {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: var(--snow-radius, 18px);
  background: var(--snow-card-bg, #FFFFFF);
  color: var(--snow-ink-secondary, #6B7280);
  font-size: 12px;
  text-align: center;
  padding: 16px;
  border: 1px dashed rgba(0, 0, 0, 0.1);
}
.snow-empty-state .snow-empty-title {
  font-weight: 600;
  color: var(--snow-ink, #111827);
  font-size: 13px;
}
.snow-kpi-host {
  --snow-primary: #007AFF;
  --snow-secondary: #AF52DE;
  --snow-tertiary: #00C7BE;
  --snow-positive: #34C759;
  --snow-warning: #FF9500;
  --snow-negative: #FF3B30;
  --snow-dark: #1C1C1E;
  --snow-ink: #111827;
  --snow-ink-secondary: #6B7280;
  --snow-ink-muted: #9CA3AF;
  --snow-on-dark: #FFFFFF;
  --snow-card-bg: #FFFFFF;
  --snow-border: #E5E7EB;
  --snow-radius: 18px;
  --snow-hover-bg: rgba(0, 122, 255, 0.055);
  --snow-hover-border: rgba(0, 122, 255, 0.14);
  --snow-selected-bg: rgba(0, 122, 255, 0.09);
  --snow-selected-border: rgba(0, 122, 255, 0.35);
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, "SF Pro Display", "Inter", Roboto, Helvetica, Arial, sans-serif;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  user-select: none;
  -webkit-font-smoothing: antialiased;
  color: var(--snow-ink, #111827);
  padding: 0;
  margin: 0;
  overflow: hidden;
  background: transparent;
}
.snow-kpi-host *,
.snow-kpi-host *::before,
.snow-kpi-host *::after {
  box-sizing: border-box;
}
.snow-kpi-card {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: var(--snow-radius, 18px);
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: var(--snow-on-dark, #FFFFFF);
  overflow: hidden;
  cursor: default;
  transition: transform 320ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 320ms cubic-bezier(0.22, 1, 0.36, 1), background 500ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-kpi-card::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.05) 0%, rgba(255, 255, 255, 0.36) 100%);
  opacity: 0.72;
}
.snow-kpi-card:hover {
  transform: translateY(-1.5px);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.1);
}
.snow-kpi-card.variant-blue,
.snow-kpi-card.variant-primary {
  --kpi-accent: var(--snow-primary, #007AFF);
  background: linear-gradient(155deg, #0073F0 0%, #007AFF 62%, #52A5FF 100%);
}
.snow-kpi-card.variant-blue.surface-solid,
.snow-kpi-card.variant-primary.surface-solid {
  background: var(--snow-primary, #007AFF);
}
.snow-kpi-card.variant-dark {
  --kpi-accent: var(--snow-dark, #1C1C1E);
  background: linear-gradient(155deg, #1C1C1E 0%, #2E2E30 58%, #525254 100%);
}
.snow-kpi-card.variant-dark.surface-solid {
  background: var(--snow-dark, #1C1C1E);
}
.snow-kpi-card.variant-teal,
.snow-kpi-card.variant-tertiary {
  --kpi-accent: var(--snow-tertiary, #00C7BE);
  background: linear-gradient(155deg, #00BBB3 0%, #00C7BE 60%, #52D9D3 100%);
}
.snow-kpi-card.variant-teal.surface-solid,
.snow-kpi-card.variant-tertiary.surface-solid {
  background: var(--snow-tertiary, #00C7BE);
}
.snow-kpi-card.variant-green,
.snow-kpi-card.variant-positive {
  --kpi-accent: var(--snow-positive, #34C759);
  background: linear-gradient(155deg, #31BB54 0%, #34C759 58%, #75D98E 100%);
}
.snow-kpi-card.variant-green.surface-solid,
.snow-kpi-card.variant-positive.surface-solid {
  background: var(--snow-positive, #34C759);
}
.snow-kpi-card.variant-purple,
.snow-kpi-card.variant-secondary {
  --kpi-accent: var(--snow-secondary, #AF52DE);
  background: linear-gradient(155deg, #A44DD1 0%, #AF52DE 60%, #C989E9 100%);
}
.snow-kpi-card.variant-purple.surface-solid,
.snow-kpi-card.variant-secondary.surface-solid {
  background: var(--snow-secondary, #AF52DE);
}
.snow-kpi-card.surface-solid::after {
  display: none;
}
.snow-kpi-card.variant-light,
.snow-kpi-card.surface-light-bordered {
  background: var(--snow-card-bg, #FFFFFF);
  color: var(--snow-ink, #111827);
  border: 1px solid var(--snow-border, #E5E7EB);
}
.snow-kpi-card.variant-light::after,
.snow-kpi-card.surface-light-bordered::after {
  display: none;
}
.snow-kpi-card.variant-light .snow-kpi-title,
.snow-kpi-card.surface-light-bordered .snow-kpi-title {
  color: var(--snow-ink-secondary, #6B7280);
}
.snow-kpi-card.variant-light .snow-kpi-icon-badge,
.snow-kpi-card.surface-light-bordered .snow-kpi-icon-badge {
  background: var(--snow-hover-bg, rgba(0, 122, 255, 0.055));
  color: var(--kpi-accent, var(--snow-primary, #007AFF));
}
.snow-kpi-card.variant-light .snow-kpi-delta-pill,
.snow-kpi-card.surface-light-bordered .snow-kpi-delta-pill {
  color: var(--snow-positive, #34C759);
  background: rgba(52, 199, 89, 0.12);
}
.snow-kpi-card.variant-light .snow-kpi-delta-pill.is-negative,
.snow-kpi-card.surface-light-bordered .snow-kpi-delta-pill.is-negative {
  color: var(--snow-negative, #FF3B30);
  background: rgba(255, 59, 48, 0.12);
}
.snow-kpi-card.is-compact {
  padding: 10px 14px;
}
.snow-kpi-card.is-compact .snow-kpi-title {
  font-size: 11.5px;
}
.snow-kpi-card.is-compact .snow-kpi-icon-badge {
  width: 22px;
  height: 22px;
  border-radius: 7px;
}
.snow-kpi-card.is-compact .snow-kpi-icon-badge svg {
  width: 13px;
  height: 13px;
}
.snow-kpi-card.is-compact .snow-kpi-body {
  align-items: center;
  gap: 8px;
}
.snow-kpi-card.is-compact .snow-kpi-value {
  font-size: 22px;
}
.snow-kpi-card.is-compact .snow-kpi-delta-wrap {
  gap: 2px;
}
.snow-kpi-card.is-compact .snow-kpi-delta-pill {
  padding: 2px 7px;
  font-size: 10.5px;
}
.snow-kpi-card.is-compact .snow-kpi-subtitle {
  font-size: 9.5px;
}
.snow-kpi-card.is-ultra-compact {
  padding: 7px 12px;
}
.snow-kpi-card.is-ultra-compact .snow-kpi-title {
  font-size: 11px;
}
.snow-kpi-card.is-ultra-compact .snow-kpi-icon-badge {
  width: 18px;
  height: 18px;
  border-radius: 6px;
}
.snow-kpi-card.is-ultra-compact .snow-kpi-icon-badge svg {
  width: 11px;
  height: 11px;
}
.snow-kpi-card.is-ultra-compact .snow-kpi-body {
  align-items: center;
  gap: 6px;
}
.snow-kpi-card.is-ultra-compact .snow-kpi-value {
  font-size: 19px;
}
.snow-kpi-card.is-ultra-compact .snow-kpi-delta-pill {
  padding: 2px 6px;
  font-size: 10px;
}
.snow-kpi-card.is-ultra-compact .snow-kpi-subtitle {
  display: none !important;
}
.snow-kpi-header {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.snow-kpi-title {
  font-size: 13px;
  font-weight: 500;
  letter-spacing: -0.005em;
  color: rgba(255, 255, 255, 0.94);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.snow-kpi-icon-badge {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.18);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--snow-on-dark, #FFFFFF);
  transition: transform 350ms cubic-bezier(0.22, 1, 0.36, 1), background-color 350ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-kpi-card:hover .snow-kpi-icon-badge {
  transform: scale(1.06);
}
.snow-kpi-body {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
}
.snow-kpi-value {
  font-size: 27px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.08;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  flex-shrink: 0;
  transition: opacity 250ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-kpi-delta-wrap {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  min-width: 0;
  flex-shrink: 1;
}
.snow-kpi-delta-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
  background: rgba(255, 255, 255, 0.18);
  color: var(--snow-on-dark, #FFFFFF);
  backdrop-filter: blur(4px);
  transition: transform 300ms cubic-bezier(0.22, 1, 0.36, 1), background-color 300ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-kpi-delta-pill svg {
  flex-shrink: 0;
}
.snow-kpi-delta-pill.is-negative {
  background: rgba(0, 0, 0, 0.16);
}
.snow-kpi-subtitle {
  font-size: 10.5px;
  opacity: 0.85;
  font-weight: 500;
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: right;
}
